package fraymus.workspace;
import org.junit.Test;
import static org.junit.Assert.*;
import org.json.*;
import java.nio.file.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;

/** Explicit worker-boundary fixtures; actual local inference and Chromium are validated separately. */
public class CreationPlanner044Test {
 static JSONObject input(){return new JSONObject().put("title","Java worker boundary").put("request","Create the retained fixture output").put("modelName",CreationTest.MODEL).put("checks",new JSONArray().put(new JSONObject().put("selector","#rows").put("expectText","3")));}
 static JSONObject authority(JSONObject e){return new JSONObject().put("goalId",e.getString("goalId")).put("id",e.getString("id")).put("nonce",e.getString("nonce"));}
 static JSONObject reply(String model){return new JSONObject().put("text",new JSONObject().put("tool","creation.submit").put("args",new JSONObject().put("html","<html><body><output id='rows'>3</output></body></html>")).toString()).put("localModel",new JSONObject().put("model",model).put("digest",CreationTest.DIGEST)).put("compute",new JSONObject().put("cpuOnly",true));}
 @Test public void acceptedGenerationKeepsOriginalGoalAndSurvivesInterfaceDetach()throws Exception{var root=Files.createTempDirectory("creation044-detach-");var entered=new CountDownLatch(1);var release=new CountDownLatch(1);try(var store=new WorkspaceStore(root);var scenes=new SceneStore(root);var brain=new BrainService(root);var goals=new GoalRunner(root,scenes,brain,store);var worker=new CreationPlanner044(root,goals,request->{assertEquals(List.of("creation.submit"),request.getJSONArray("allowedTools").toList());assertTrue(request.getString("prompt").contains("Create the retained fixture output"));entered.countDown();assertTrue(release.await(5,TimeUnit.SECONDS));return reply(CreationTest.MODEL);},id->{})){
  var goal=goals.startCreation(input());var e=CreationTest.claim(goals,"creation.generate");var started=worker.start(authority(e));assertTrue(entered.await(5,TimeUnit.SECONDS));assertEquals(started.getString("id"),worker.start(authority(e)).getString("id"));goals.hostDetached042(worker.retained());assertEquals("waiting-host",goals.read(goal.getString("id")).getString("status"));assertEquals(Set.of(goal.getString("id")),worker.retained());release.countDown();var verify=CreationTest.claim(goals,"creation.test");assertEquals(goal.getString("id"),verify.getString("goalId"));assertTrue(store.read(verify.getJSONObject("report").getString("id")).getJSONObject("contents").getString("index.html").contains("id='rows'"));assertEquals("completed",worker.read(started.getString("id")).getString("status"));goals.cancel(goal.getString("id"));
 }finally{release.countDown();}}
 @Test public void cancelledGenerationCannotApplyItsLateModelReply()throws Exception{var root=Files.createTempDirectory("creation044-cancel-");var entered=new CountDownLatch(1);var release=new CountDownLatch(1);try(var store=new WorkspaceStore(root);var scenes=new SceneStore(root);var brain=new BrainService(root);var goals=new GoalRunner(root,scenes,brain,store);var worker=new CreationPlanner044(root,goals,request->{entered.countDown();assertTrue(release.await(5,TimeUnit.SECONDS));return reply(CreationTest.MODEL);},id->{})){var goal=goals.startCreation(input());var e=CreationTest.claim(goals,"creation.generate");var j=worker.start(authority(e));assertTrue(entered.await(5,TimeUnit.SECONDS));worker.cancel(goal.getString("id"));goals.cancel(goal.getString("id"));release.countDown();Thread.sleep(150);assertEquals("interrupted",worker.read(j.getString("id")).getString("status"));assertEquals("cancelled",goals.read(goal.getString("id")).getString("status"));assertEquals(0,store.artifacts().length());}finally{release.countDown();}}
 @Test public void foreignHostNonceCannotCreateAJavaModelRequest()throws Exception{var root=Files.createTempDirectory("creation044-foreign-");var calls=new AtomicInteger();try(var store=new WorkspaceStore(root);var scenes=new SceneStore(root);var brain=new BrainService(root);var goals=new GoalRunner(root,scenes,brain,store);var worker=new CreationPlanner044(root,goals,request->{calls.incrementAndGet();return reply(CreationTest.MODEL);},id->{})){var goal=goals.startCreation(input());var e=CreationTest.claim(goals,"creation.generate");assertThrows(IllegalStateException.class,()->worker.start(authority(e).put("nonce",UUID.randomUUID().toString())));assertEquals(0,calls.get());goals.cancel(goal.getString("id"));}}
 @Test public void changedModelAdmissionCannotWriteAnArtifact()throws Exception{var root=Files.createTempDirectory("creation044-model-");try(var store=new WorkspaceStore(root);var scenes=new SceneStore(root);var brain=new BrainService(root);var goals=new GoalRunner(root,scenes,brain,store);var worker=new CreationPlanner044(root,goals,request->reply("foreign-model"),id->{})){var goal=goals.startCreation(input());var e=CreationTest.claim(goals,"creation.generate");var j=worker.start(authority(e));for(int i=0;i<500&&worker.read(j.getString("id")).getString("status").equals("running");i++)Thread.sleep(10);assertEquals("interrupted",worker.read(j.getString("id")).getString("status"));assertEquals("interrupted",goals.read(goal.getString("id")).getString("status"));assertEquals(0,store.artifacts().length());}}
 @Test public void wrongStageAndInvalidArgumentsAreRefusedBeforeBoundedRetryCanWrite()throws Exception{var root=Files.createTempDirectory("creation044-retry-");var calls=new AtomicInteger();try(var store=new WorkspaceStore(root);var scenes=new SceneStore(root);var brain=new BrainService(root);var goals=new GoalRunner(root,scenes,brain,store);var worker=new CreationPlanner044(root,goals,request->{int n=calls.getAndIncrement();assertTrue(n<3);assertEquals(0,store.artifacts().length());var r=reply(CreationTest.MODEL);if(n==0)r.put("text",new JSONObject().put("tool","creation.contract").put("args",new JSONObject()).toString());if(n==1){assertTrue(request.getString("prompt").contains("NEVER executed"));r.put("text",new JSONObject().put("tool","creation.submit").put("args",new JSONObject().put("html",42)).toString());}return r;},id->{})){var goal=goals.startCreation(input());var e=CreationTest.claim(goals,"creation.generate");var j=worker.start(authority(e));var verify=CreationTest.claim(goals,"creation.test");var done=worker.read(j.getString("id"));assertEquals("completed",done.getString("status"));assertEquals(3,done.getInt("attempts"));assertEquals(2,done.getJSONArray("rejections").length());for(Object raw:done.getJSONArray("rejections"))assertFalse(((JSONObject)raw).getBoolean("executed"));assertEquals(1,store.artifacts().length());assertTrue(store.read(verify.getJSONObject("report").getString("id")).getJSONObject("contents").getString("index.html").contains("id='rows'"));assertTrue(goals.read(goal.getString("id")).getJSONArray("testSteps").similar(input().getJSONArray("checks")));goals.cancel(goal.getString("id"));}}
}
